  1640  static int set_defaults (struct cfgst *cfgst, void *parent, int isattr, struct cfgelem const * const cfgelem)
  1641  {
  1642    int ok = 1;
  1643    for (const struct cfgelem *ce = cfgelem; ce && ce->name; ce++)
  1644    {
  1645      struct cfgst_nodekey key;
  1646      key.e = ce;
  1647      key.p = parent;
  1648      // running over internal tables, so stack must be large enough
  1649      cfgst_push_nofail (cfgst, isattr, ce, parent);
  1650      if (ce->multiplicity <= 1)
  1651      {
  1652        if (ddsrt_avl_lookup (&cfgst_found_treedef, &cfgst->found, &key) == NULL)
  1653        {
  1654          if (ce->update)
  1655          {
  1656            int ok1;
  1657            cfgst_push_nofail (cfgst, 0, NULL, NULL);
  1658            ok1 = set_default (cfgst, parent, ce);
  1659            cfgst_pop (cfgst);
  1660            ok = ok && ok1;
  1661          }
