  1663        if (ce->children)
  1664          ok = ok && set_defaults (cfgst, parent, 0, ce->children);
  1665        if (ce->attributes)
  1666          ok = ok && set_defaults (cfgst, parent, 1, ce->attributes);
  1667      }
  1668      cfgst_pop (cfgst);
  1669    }
