  1750  static void free_configured_element (struct cfgst *cfgst, void *parent, struct cfgelem const * const ce)
  1751  {
  1752    struct cfgst_nodekey key;
  1753    struct cfgst_node *n;
  1754    if (ce->name[0] == '>') /* moved, so don't care */
  1755      return;
  1756    key.e = ce;
  1757    key.p = parent;
  1758    if ((n = ddsrt_avl_lookup (&cfgst_found_treedef, &cfgst->found, &key)) != NULL)
  1759    {
  1760      if (ce->free && n->count > n->failed)
  1761        ce->free (cfgst, parent, ce);
  1762      n->count = n->failed = 0;
  1763    }
  1764
  1765    if (ce->multiplicity <= 1)
  1766    {
  1767      if (ce->children)
  1768        free_configured_elements (cfgst, parent, ce->children);
  1769      if (ce->attributes)
  1770        free_configured_elements (cfgst, parent, ce->attributes);
  1771    }
  1772    else
  1773    {
  1774      /* FIXME: this used to require free_all_elements because there would be no record stored for
  1775         configuration elements within lists, but with that changed, I think this can now just use
  1776         free_configured_elements */
  1777      struct ddsi_config_listelem *p = cfg_deref_address (cfgst, parent, ce);
  1778      while (p) {
  1779        struct ddsi_config_listelem * const p1 = p->next;
  1780        if (ce->attributes)
  1781          free_all_elements (cfgst, p, ce->attributes);
  1782        if (ce->children)
  1783          free_all_elements (cfgst, p, ce->children);
  1784        ddsrt_free (p);
  1785        p = p1;
  1786      }
  1787    }
  1788  }
